'use client';

import {version as appVersion} from '../package.json';
import SheetPicker,{type ImportCheck,type SheetRequest,type SheetSelection,type SheetChoice} from './sheet-picker';
import OperationsPanel,{type Profile} from './operations-panel';
import { Fragment, useCallback, useEffect, useRef, useState } from 'react';
import { ArrowDownToLine, ArrowRight, Check, CheckCheck, ChevronLeft, ChevronRight, CircleAlert, Database, FileSpreadsheet, Files, FolderOpen, History, LayoutDashboard, LoaderCircle, Plus, Search, Settings2, ShieldCheck, Sparkles, Upload, X } from 'lucide-react';

type FileInfo = {sheet_review?:(SheetChoice&{selected:boolean;rows:number;gross:string})[]; id:string;name:string;kind:string;rows:number;error:string|null };
type Totals = {source_cost_total:string;cost_rows:number;calculated_gross:string;gross_rows:number;source_sales_ex_vat:string;exvat_rows:number;rows:number;ready:number;blocked:number;qty:string;gross:string;net:string;net_rows:number;calculated_net:string;calculated_rows:number;default_discount_rows:number};
type BranchGroup = Totals & {key:string;branch:string;branch_code:string};
type Group = Totals & {customer:string;branches:number;branch_groups:BranchGroup[]};
type Batch = {below_cost_rows:number; id:string;created:string;period:string;files:FileInfo[];rows:number;ready:number;blocked:number;groups:Group[];file_errors:number;exportable:boolean;merged_rows:number;merged_qty:string;merged_gross:string;merged_net:string };
type CostConfirmation = {confirmed_by:string;at:string;reason:string;vat_basis:string;comparable:boolean;evidence:string};
type SaleRow = {source_reference?:{gross:string|null;net:string|null};valuation?:{sale_basis:string;cost_basis:string;settlement_basis:string;vat_rate:string;note:string};comparison_basis:string;comparison_sale_price:string|null;comparison_cost_price:string|null;below_cost_status:'none'|'pending'|'confirmed';below_cost_confirmation:CostConfirmation|null;below_cost_confirmations:CostConfirmation[];below_cost_difference:string|null;below_cost_after_discount_difference:string|null;source_gp:string|null;source_mg:string|null;discount_kind:string;source_cost_price:string|null;source_cost_total:string|null;source_cost_origin:string;source_sales_ex_vat:string|null;calculated_gross:string|null; id:string;file_id:string;source:string;sheet:string;line:number;customer:string;branch:string;branch_code?:string;sku:string;barcode:string;partner:string;qty:string;price:string;discount:string;gross:string|null;net:string|null;calculated_net:string|null;delta:string|null;vat:string;date:string;errors:string[];warnings:string[];raw:Record<string,string>;status:string;sku_origin:string;discount_origin:string;discount_defaulted?:boolean;edits:unknown[];source_columns?:string };
type MergedRow = {sku:string;price:string;qty:string;discount:string;gross:string;net:string;source_count:number};
type HistoryItem = { id:string;created:string;period:string;rows:number };
const number = (n:string|number|null|undefined, places=2) => n==null ? '—' : Number(n).toLocaleString('th-TH',{maximumFractionDigits:places,minimumFractionDigits:places});
const displayDiscount = (value:string) => value.split('+').map(part=>{
  const text=part.trim().replace(/%$/,'');
  if(!/^\d+(?:\.\d+)?$/.test(text))return part;
  return Number(text).toLocaleString('en-US',{useGrouping:false,minimumFractionDigits:2,maximumFractionDigits:2})+'%';
}).join('+');
async function api<T>(url:string, init?:RequestInit):Promise<T> {
  const response=await fetch('/api'+url,init);
  if(!response.ok){const body=await response.json().catch(()=>({detail:'ติดต่อระบบประมวลผลไม่ได้'}));throw new Error(typeof body.detail==='string'?body.detail:JSON.stringify(body.detail));}
  return response.json();
}
const json = (method:string,body:unknown):RequestInit => ({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});

export default function Home(){
  const [checkedIds,setCheckedIds]=useState<string[]>([]);const [bulkOpen,setBulkOpen]=useState(false);const [bulkField,setBulkField]=useState('discount');const [bulkValue,setBulkValue]=useState('');
  const [sheetRequest,setSheetRequest]=useState<SheetRequest|null>(null);
  const sheetResolver=useRef<((selection:SheetSelection|null)=>void)|null>(null);
  const finishSheets=useCallback((selection:SheetSelection|null)=>{const resolve=sheetResolver.current;sheetResolver.current=null;setSheetRequest(null);resolve?.(selection);},[]);
  const [profiles,setProfiles]=useState<Profile[]>([]);const [importProfile,setImportProfile]=useState('');
  const [batch,setBatch]=useState<Batch|null>(null);
  const [history,setHistory]=useState<HistoryItem[]>([]);
  const [tab,setTab]=useState<'rows'|'mapping'|'totals'|'merged'|'below-cost'|'operations'>('rows');
  const [rows,setRows]=useState<SaleRow[]>([]);
  const [total,setTotal]=useState(0);
  const [merged,setMerged]=useState<MergedRow[]>([]);const [mergedPage,setMergedPage]=useState(1);const [mergedTotal,setMergedTotal]=useState(0);const [exactSku,setExactSku]=useState('');
  const [belowCost,setBelowCost]=useState('');
  const [branchKey,setBranchKey]=useState('');const [expandedShops,setExpandedShops]=useState<string[]>([]);
  const [query,setQuery]=useState(''); const [customer,setCustomer]=useState(''); const [status,setStatus]=useState(''); const [page,setPage]=useState(1);
  const [busy,setBusy]=useState(''); const [fetching,setFetching]=useState(false); const [notice,setNotice]=useState<{text:string;error:boolean}|null>(null);
  const [period,setPeriod]=useState('2026-08'); const [revision,setRevision]=useState(0); const [selected,setSelected]=useState<SaleRow|null>(null); const [dragging,setDragging]=useState(false);
  const [ruleCustomer,setRuleCustomer]=useState('Outlet G624');const [ruleDiscount,setRuleDiscount]=useState('');const [ruleRemember,setRuleRemember]=useState(true);
  const fileInput=useRef<HTMLInputElement>(null); const masterInput=useRef<HTMLInputElement>(null);
  const run=async(fn:()=>Promise<void>,label:string)=>{setBusy(label);setNotice(null);try{await fn();}catch(e){setNotice({text:'ดำเนินการไม่สำเร็จ: '+(e instanceof Error?e.message:'เกิดข้อผิดพลาด'),error:true});}finally{setBusy('');}};
  const reloadProfiles=useCallback(async()=>{setProfiles(await api<Profile[]>('/profiles'));},[]);
  useEffect(()=>{reloadProfiles().catch(e=>setNotice({error:true,text:e.message}));},[reloadProfiles]);
  const refresh=useCallback(async(id:string)=>{const b=await api<Batch>('/batches/'+id);setBatch(b);setPeriod(b.period);setRevision(v=>v+1);setHistory(await api<HistoryItem[]>('/batches'));},[]);
  useEffect(()=>{api<HistoryItem[]>('/batches').then(async h=>{setHistory(h);if(h[0])await refresh(h[0].id);}).catch(e=>setNotice({text:'เปิด backend ก่อนใช้งาน: '+e.message,error:true}));},[refresh]);
  useEffect(()=>{
    if(!batch){setRows([]);return;}
    const abort=new AbortController();setFetching(true);
    const params=new URLSearchParams({q:query,customer,status,sku:exactSku,branch_key:branchKey,below_cost:belowCost,page:String(page),size:'30'});
    const timer=setTimeout(()=>api<{rows:SaleRow[];total:number}>(`/batches/${batch.id}/rows?${params}`,{signal:abort.signal}).then(r=>{setRows(r.rows);setTotal(r.total);}).catch(e=>{if(e.name!=='AbortError')setNotice({text:e.message,error:true});}).finally(()=>{if(!abort.signal.aborted)setFetching(false);}),180);
    return()=>{clearTimeout(timer);abort.abort();};
  },[batch?.id,query,customer,status,page,revision,exactSku,branchKey,belowCost]);
  useEffect(()=>{
    if(!batch){setMerged([]);setMergedTotal(0);return;}
    if(tab!=='merged')return;
    setMerged([]);
    const abort=new AbortController();
    api<{rows:MergedRow[];total:number}>(`/batches/${batch.id}/merged?page=${mergedPage}`,{signal:abort.signal}).then(r=>{setMerged(r.rows);setMergedTotal(r.total);}).catch(e=>{if(e.name!=='AbortError')setNotice({text:e.message,error:true});});
    return()=>abort.abort();
  },[batch?.id,tab,mergedPage,revision]);
  useEffect(()=>{setCheckedIds([]);setBulkOpen(false);},[batch?.id,query,customer,status,page,branchKey,exactSku,revision,belowCost]);
  const resetFilters=()=>{setBelowCost('');setBranchKey('');setExpandedShops([]);setExactSku('');setMergedPage(1);setPage(1);setCustomer('');setQuery('');setStatus('');};
  const ensureBatch=async()=> batch || await api<Batch>('/batches',json('POST',{period}));
  const importNotice=(result:Batch,previousFileIds:string[])=>{
    const added=result.files.filter(f=>!previousFileIds.includes(f.id));const failed=added.filter(f=>f.error);const passed=added.length-failed.length;
    const count=added.reduce((sum,f)=>sum+f.rows,0);
    if(failed.length)setNotice({text:`${passed?'นำเข้าสำเร็จบางไฟล์':'นำเข้าไม่สำเร็จ'} · สำเร็จ ${passed} ไฟล์ / ไม่สำเร็จ ${failed.length} ไฟล์ · ${number(count,0)} รายการ · ${failed.map(f=>`${f.name}: ${f.error}`).join(' · ')}`,error:true});
    else setNotice({text:`นำเข้าสำเร็จ ${added.length} ไฟล์ · ${number(count,0)} รายการ${result.blocked?` · มี ${number(result.blocked,0)} รายการต้องตรวจแก้ในชุดข้อมูล`:''}`,error:false});
  };
  const loadSamples=()=>run(async()=>{const b=await ensureBatch();setBatch(b);const result=await api<Batch>(`/batches/${b.id}/sample`,{method:'POST'});await refresh(b.id);resetFilters();importNotice(result,b.files.map(f=>f.id));},'กำลังอ่านไฟล์ตัวอย่างทั้ง 5 แหล่ง…');
  const uploadFiles=(files:File[])=>{if(!files.length)return;run(async()=>{const b=await ensureBatch();setBatch(b);const checkData=new FormData();files.forEach(f=>checkData.append('files',f));checkData.append('profile_id',importProfile);const checks=await api<ImportCheck[]>(`/batches/${b.id}/check-upload`,{method:'POST',body:checkData});if(checks.some(c=>c.same_batch))throw new Error('ไฟล์ซ้ำในชุดนี้: '+checks.filter(c=>c.same_batch).map(c=>c.name).join(', '));const duplicates=checks.filter(c=>c.previous.length);let allowDuplicate=false;if(duplicates.length){allowDuplicate=window.confirm('ไฟล์นี้เคยนำเข้าแล้วในชุดอื่น:\n'+duplicates.map(c=>`${c.name} · งวด ${c.previous.map(p=>p.period).join(', ')}`).join('\n')+'\nต้องการนำเข้าซ้ำโดยตั้งใจหรือไม่?');if(!allowDuplicate){setNotice({error:false,text:'ยกเลิกการนำเข้าซ้ำแล้ว'});return;}}let selection:SheetSelection={};if(checks.some(c=>c.sheets.length>1)){const result=await new Promise<SheetSelection|null>(resolve=>{sheetResolver.current=resolve;setSheetRequest({checks,resolve});});if(!result){setNotice({text:'ยกเลิกการนำเข้าแล้ว',error:false});return;}selection=result;}const data=new FormData();files.forEach(f=>data.append('files',f));data.append('sheet_selection',JSON.stringify(selection));data.append('profile_id',importProfile);data.append('allow_duplicate',String(allowDuplicate));const result=await api<Batch>(`/batches/${b.id}/upload`,{method:'POST',body:data});await refresh(b.id);resetFilters();importNotice(result,b.files.map(f=>f.id));},'กำลังตรวจไฟล์ซ้ำ นำเข้า และตรวจยอด…');};
  const newBatch=()=>{setBatch(null);setRows([]);setTotal(0);resetFilters();setTab('rows');setNotice(null);};
  const clearImports=()=>{if(!window.confirm('ล้างชุดข้อมูลนำเข้าและประวัติทั้งหมด? ไฟล์ต้นฉบับ Mapping ฐานราคา รูปแบบนำเข้า และทะเบียน Import/Export จะยังอยู่'))return;run(async()=>{const cleared=await api<{cleanup_pending:number}>('/batches',{method:'DELETE'});newBatch();setHistory([]);setSelected(null);setNotice({text:'ล้างข้อมูลนำเข้าแล้ว พร้อมนำเข้าไฟล์ชุดใหม่'+(cleared.cleanup_pending?' · มีไฟล์รอลบ '+cleared.cleanup_pending+' ไฟล์ ระบบจะลองใหม่เมื่อเริ่ม Backend':'') ,error:false});},'กำลังล้างข้อมูลนำเข้า…');};
  const uploadMaster=(file:File)=>run(async()=>{if(!batch)throw new Error('นำเข้ารายงานก่อนเพิ่มตารางอ้างอิง');const data=new FormData();data.append('file',file);data.append('preview','true');const preview=await api<{mappings:number;resolved:number;changes:{before:string;after:string}[]}>(`/batches/${batch.id}/master`,{method:'POST',body:data});if(!window.confirm(`Master Mapping ${preview.mappings} คู่ จะเปลี่ยนรหัสว่าง/ชั่วคราว ${preview.resolved} รายการ\n${preview.changes.slice(0,10).map(c=>`${c.before||'(ว่าง)'} → ${c.after}`).join('\n')}\nยืนยันบันทึกหรือไม่? SKU จริงและค่าที่แก้เองจะคงเดิม`)){setNotice({text:'ยกเลิก Mapping แล้ว',error:false});return;}data.set('preview','false');const r=await api<{mappings:number;resolved:number}>(`/batches/${batch.id}/master`,{method:'POST',body:data});await refresh(batch.id);setNotice({text:`บันทึก ${r.mappings} mapping · จับคู่เพิ่ม ${r.resolved} รายการ`,error:false});},'กำลังจับคู่ SKU…');
  const exportFile=(scope:'all'|'ready')=>run(async()=>{
    if(!batch)return;
    const res=await fetch(`/api/batches/${batch.id}/export?scope=${scope}`);
    if(!res.ok){const e=await res.json();throw new Error(e.detail);}
    const exported=Number(res.headers.get('X-Exported-Rows'));
    const included=Number(res.headers.get('X-Exported-Source-Rows'));
    const skipped=Number(res.headers.get('X-Skipped-Rows'));const repeated=Number(res.headers.get('X-Previous-Identical-Exports')||0);
    const roundingDelta=res.headers.get('X-Export-Rounding-Delta')||'0';
    const failedFiles=Number(res.headers.get('X-Skipped-Files'));
    const url=URL.createObjectURL(await res.blob());const a=document.createElement('a');
    a.href=url;a.download=`Consign_${batch.period}${scope==='ready'?'_ready':''}.xlsx`;a.click();
    setTimeout(()=>URL.revokeObjectURL(url),1000);
    setNotice({text:`ส่งออกแล้ว ${number(exported,0)} SKU จาก ${number(included,0)} รายการ · ยังไม่ส่งออก ${number(skipped,0)} รายการ${failedFiles?` และ ${failedFiles} ไฟล์ที่อ่านไม่สำเร็จ`:''} · ชีต Sample ตามแม่แบบ · ส่วนลด 2 ตำแหน่ง ส่วนต่างยอดจากการปัด ${number(roundingDelta)} บาท${repeated?` · เนื้อหานี้เคย Export แล้ว ${repeated} ครั้ง ตรวจสอบก่อนส่งซ้ำ`:''}`,error:false});
  },'กำลังตรวจยอดและสร้าง Excel…');
  const applyRule=()=>run(async()=>{if(!batch)return;const r=await api<{updated:number}>(`/batches/${batch.id}/discount-rule`,json('POST',{customer:ruleCustomer,discount:ruleDiscount,remember:ruleRemember}));await refresh(batch.id);setNotice({text:`ปรับส่วนลดให้ ${r.updated} รายการที่เป็นค่าเริ่มต้น`,error:false});},'กำลังตรวจส่วนลด…');
  const showBranch=(shop:string,key='')=>{setBelowCost('');setExactSku('');setQuery('');setCustomer(shop);setBranchKey(key);setStatus('');setPage(1);setTab('rows');};
  const bulkSave=()=>run(async()=>{if(!batch)return;const result=await api<{updated:number;blocked:number}>(`/batches/${batch.id}/bulk-edit`,json('POST',{ids:checkedIds,field:bulkField,value:bulkValue}));await refresh(batch.id);setCheckedIds([]);setBulkOpen(false);setBulkValue('');setNotice({text:`บันทึกแล้ว ${result.updated} รายการ${result.blocked?` · ยังมี ${result.blocked} รายการต้องตรวจยอด`:''}`,error:false});},'กำลังบันทึกหลายรายการและตรวจยอด…');
  const restoreWorkspace=async()=>{const h=await api<HistoryItem[]>('/batches');setHistory(h);resetFilters();setSelected(null);setImportProfile('');if(h[0])await refresh(h[0].id);else{setBatch(null);setRows([]);setTotal(0);}await reloadProfiles();};
  const qty=batch?.groups.reduce((s,g)=>s+Number(g.qty),0)||0;

  return <div className="workspace">
    <aside className="sidebar" inert={!!busy}>
      <a className="brand" href="/"><span className="brandmark"><Files size={23}/></span><span>ConsignmentSystem<small>SALES OPERATIONS</small></span></a>
      <div className="workspace-label">WORKSPACE <span>LOCAL</span></div>
      <nav aria-label="เมนูหลัก">
        <button className={tab==='rows'?'active':''} onClick={()=>setTab('rows')}><LayoutDashboard size={18}/> รายการนำเข้า <span className="nav-count">{batch?.files.length||0}</span></button>
        <button className={tab==='mapping'?'active':''} onClick={()=>setTab('mapping')}><Settings2 size={18}/> กติกาและ Mapping</button>
        <button className={tab==='totals'?'active':''} onClick={()=>setTab('totals')}><ShieldCheck size={18}/> ตรวจสอบยอด</button>
        <button className={tab==='operations'?'active':''} onClick={()=>setTab('operations')}><Settings2 size={18}/> ตั้งค่าและประวัติ</button>
      </nav>
      <div className="history-title"><History size={14}/> ชุดข้อมูลล่าสุด</div>
      <div className="history-list">{history.slice(0,6).map(h=><button key={h.id} disabled={!!busy} className={batch?.id===h.id?'current':''} onClick={()=>run(async()=>{await refresh(h.id);resetFilters();},'กำลังเปิดชุดข้อมูล…')}><span className="history-dot"/><span>{h.period}<small>{h.rows.toLocaleString()} รายการ · {new Date(h.created).toLocaleDateString('th-TH',{day:'numeric',month:'short'})}</small></span></button>)}{!history.length&&<p>ยังไม่มีประวัติการนำเข้า</p>}</div>
      <div className="sidebar-foot"><div className="local-dot"/><span>Local · Beta 1<small>ข้อมูลจัดเก็บบนเครื่องนี้</small></span><span className="version">v{appVersion}</span></div>
    </aside>
    <main inert={!!busy} aria-busy={!!busy}>
      <header className="topbar"><div>Workspace <span>/</span> <strong>ยอดขายฝากขาย</strong></div><div className="top-right"><span className="demo-tag">BETA 1</span><span className="avatar">W</span></div></header>
      <div className="main-content">
        <section className="heading"><div><div className="eyebrow">CONSIGNMENT SALES</div><h1>รวมข้อมูลขาย ให้พร้อมใช้งาน<span>.</span></h1><p>นำเข้ารายงานต่างรูปแบบ ตรวจข้อมูล แล้วส่งออกเป็นไฟล์เดียว</p></div><div className="heading-actions"><button className="text-button" onClick={clearImports} disabled={!!busy||!history.length}><X size={15}/> ล้างข้อมูลนำเข้าทั้งหมด</button><button className="button secondary" onClick={newBatch} disabled={!!busy}><Plus size={17}/> ชุดข้อมูลใหม่</button></div></section>
        <section className="steps" aria-label="ขั้นตอน"><div className="step complete"><span>01</span> นำเข้าไฟล์</div><ArrowRight size={15}/><div className={`step ${batch?.rows?'complete':''}`}><span>02</span> ตรวจ Mapping และยอด</div><ArrowRight size={15}/><div className={`step ${batch?.exportable?'complete':''}`}><span>03</span> ส่งออก Excel</div><div className="template-note"><FileSpreadsheet size={15}/> Consign_sample.xlsx</div></section>
        {notice&&<div role={notice.error?'alert':'status'} className={`notice ${notice.error?'error':'success'}`}>{notice.error?<CircleAlert size={18}/>:<Check size={18}/>}<span>{notice.text}</span><button aria-label="ปิดข้อความ" onClick={()=>setNotice(null)}><X size={17}/></button></div>}

        <section className="import-grid">
          <div className={`dropzone ${dragging?'dragging':''}`} onDragOver={e=>{e.preventDefault();setDragging(true);}} onDragLeave={()=>setDragging(false)} onDrop={e=>{e.preventDefault();setDragging(false);if(!busy)uploadFiles(Array.from(e.dataTransfer.files));}}>
            <div className="upload-icon"><Upload size={23}/></div><div className="drop-copy"><h2>วางไฟล์รายงานขายที่นี่</h2><p>Excel หรือ PDF ข้อความ · สูงสุด 25 MB ต่อไฟล์</p><label className="import-profile-label">รูปแบบนำเข้า<select aria-label="รูปแบบสำหรับ Import" value={importProfile} disabled={!!busy} onChange={e=>setImportProfile(e.target.value)}><option value="">ตรวจอัตโนมัติ · 5 รูปแบบเดิม</option>{profiles.map(p=><option key={p.id} value={p.id}>{p.config.name} · v{p.version}</option>)}</select></label><div className="upload-actions"><button className="button primary" disabled={!!busy} onClick={()=>fileInput.current?.click()}><Plus size={16}/> เลือกไฟล์</button><button className="text-button" disabled={!!busy} onClick={loadSamples}><FolderOpen size={16}/> โหลดชุดตัวอย่าง <ArrowRight size={15}/></button></div></div>
            <input ref={fileInput} aria-label="อัปโหลดรายงาน" type="file" accept=".xlsx,.pdf" multiple hidden onChange={e=>{uploadFiles(Array.from(e.target.files||[]));e.target.value='';}}/>
          </div>
          <div className="batch-card"><span className="card-label">งวดรายงาน</span><label className="sr-only" htmlFor="period">งวดรายงาน</label><input id="period" type="month" value={period} disabled={!!batch||!!busy} onChange={e=>setPeriod(e.target.value)}/><p>เก็บวันที่ขายและรายการคืนตามต้นทาง<br/>รวมทุกลูกค้าและสาขาในไฟล์ส่งออกเดียว</p><span className="subtle-chip"><ShieldCheck size={13}/> ต้นฉบับเก็บไว้ตรวจย้อนหลัง</span></div>
        </section>
        <section className="stats">
          <div className="stat"><span>ไฟล์นำเข้า <Files size={17}/></span><strong>{batch?.files.length||0}<small>ไฟล์</small></strong><p>Excel และ PDF ในชุดนี้</p></div>
          <div className="stat"><span>รายการขาย <FileSpreadsheet size={17}/></span><strong>{number(batch?.rows||0,0)}<small>รายการ</small></strong><p>จำนวนสุทธิ {number(qty,0)} ชิ้น</p></div>
          <div className="stat green"><span>พร้อมส่งออก <CheckCheck size={17}/></span><strong>{number(batch?.ready||0,0)}<small>รายการ</small></strong><p>ข้อมูลจำเป็นครบและผ่านการตรวจยอด</p></div>
          <button className="stat amber" onClick={()=>{resetFilters();setTab('rows');setStatus('blocked');}}><span>ต้องตรวจแก้ <CircleAlert size={17}/></span><strong>{number(batch?.blocked||0,0)}<small>รายการ</small></strong><p>{batch?.file_errors?`และ ${batch.file_errors} ไฟล์อ่านไม่สำเร็จ`:'SKU / ส่วนลด / ยอดที่ยังไม่ตรง'}</p></button>
        </section>
        {!!batch?.files.length&&<section className="file-strip" aria-label="ไฟล์นำเข้า">{batch.files.map(f=><div className={`file-chip ${f.error?'file-error':''}`} key={f.id}><FileSpreadsheet size={17}/><a title={f.error||f.name} href={`/api/batches/${batch.id}/files/${f.id}`}><strong>{f.kind}</strong><span>{f.error?'อ่านไม่สำเร็จ':`${f.rows.toLocaleString()} รายการ`}</span></a><button title="นำไฟล์ออกจากชุด" aria-label={`นำ ${f.name} ออก`} disabled={!!busy} onClick={()=>run(async()=>{await api(`/batches/${batch.id}/files/${f.id}`,{method:'DELETE'});await refresh(batch.id);},'กำลังนำไฟล์ออก…')}><X size={13}/></button>{f.error&&<div className="file-error-detail">{f.error}</div>}</div>)}</section>}
        {batch?.files.some(f=>f.sheet_review)&&<details className="sheet-report"><summary>ตรวจผลนำเข้าแยกตามชีต</summary>{batch.files.filter(f=>f.sheet_review).map(f=><div key={f.id}><strong>{f.name}</strong>{f.sheet_review?.map(sheet=><p key={sheet.name}>{sheet.name} · {sheet.selected?`นำเข้า ${sheet.rows} รายการ · ยอดก่อนหัก ${number(sheet.gross)} บาท`:`ข้าม · ${sheet.reason||'ไม่ได้เลือก'}`}</p>)}</div>)}</details>}
        <section className="data-panel">
          <div className="panel-top"><div className="tabs"><button className={tab==='rows'?'selected':''} onClick={()=>setTab('rows')}>รายการขาย <span>{number(batch?.rows||0,0)}</span></button><button className={tab==='merged'?'selected':''} onClick={()=>{setTab('merged');setMergedPage(1);}}>รวมตาม SKU</button><button className={tab==='mapping'?'selected':''} onClick={()=>setTab('mapping')}>Mapping</button><button className={tab==='totals'?'selected':''} onClick={()=>setTab('totals')}>ตรวจยอด</button><button className={tab==='below-cost'?'selected':''} onClick={()=>setTab('below-cost')}>ต่ำกว่าต้นทุน <span>{batch?.below_cost_rows||0}</span></button><button className={tab==='operations'?'selected':''} onClick={()=>setTab('operations')}>ตั้งค่า / ประวัติ</button></div><span className="saved-label"><span className="local-dot"/> บันทึกในเครื่อง</span></div>
          {tab==='operations'&&<OperationsPanel batch={batch} profiles={profiles} onProfilesChanged={reloadProfiles} onDataChanged={async()=>{if(batch)await refresh(batch.id);}} onRestored={restoreWorkspace}/>}
          {tab==='rows'&&<>
            <div className="filters"><div className="search-box"><Search size={17}/><input aria-label="ค้นหารายการ" placeholder="ค้นหา SKU, Barcode หรือสาขา…" value={query} onChange={e=>{setExactSku('');setQuery(e.target.value);setPage(1);}}/></div><select aria-label="กรองลูกค้า" value={customer} onChange={e=>{setCustomer(e.target.value);setBranchKey('');setPage(1);}}><option value="">ลูกค้าทั้งหมด</option>{batch?.groups.map(g=><option key={g.customer}>{g.customer}</option>)}</select><select aria-label="กรองสาขา" disabled={!customer} value={branchKey} onChange={e=>{setBranchKey(e.target.value);setPage(1);}}><option value="">ทุกสาขา</option>{batch?.groups.find(g=>g.customer===customer)?.branch_groups.map(b=><option key={b.key} value={b.key}>{b.branch_code?`${b.branch_code} · `:''}{b.branch}</option>)}</select><select aria-label="กรองขายต่ำกว่าต้นทุน" value={belowCost} onChange={e=>{setBelowCost(e.target.value);setPage(1);}}><option value="">ทุกเงื่อนไขต้นทุน</option><option value="all">ขายต่ำกว่าต้นทุนทั้งหมด</option><option value="pending">ต่ำกว่าต้นทุน · รอตรวจสอบ</option><option value="confirmed">ต่ำกว่าต้นทุน · ยืนยันแล้ว</option></select><select aria-label="กรองสถานะ" value={status} onChange={e=>{setStatus(e.target.value);setPage(1);}}><option value="">ทุกสถานะ</option><option value="blocked">ต้องตรวจแก้</option><option value="ready">พร้อมส่งออก</option></select></div>
            <div className="bulk-toolbar"><span>เลือก {checkedIds.length} รายการ <small>เลือกได้ครั้งละหน้าปัจจุบัน · เปลี่ยนหน้า/ตัวกรองจะล้างการเลือก</small></span><button className="button secondary" disabled={!checkedIds.length||fetching||!!busy} onClick={()=>setBulkOpen(v=>!v)}><Settings2 size={15}/> แก้ไขรายการที่เลือก</button>{checkedIds.length>0&&<button className="text-button" onClick={()=>{setCheckedIds([]);setBulkOpen(false);}}>ยกเลิกการเลือก</button>}</div>
            {bulkOpen&&<div className="bulk-editor"><label>ช่องที่ต้องการแก้<select aria-label="ช่องแก้ไขหลายรายการ" value={bulkField} onChange={e=>{setBulkField(e.target.value);setBulkValue('');}}><option value="discount">Discount / ส่วนลด</option><option value="price">Price / ราคาต่อหน่วย</option><option value="qty">Qty / จำนวนต่อรายการ</option><option value="net">ยอดสุทธิรวมต่อรายการ</option><option value="sku">Items / SKU</option></select></label><label>ค่าใหม่สำหรับทุกรายการที่เลือก<input aria-label="ค่าใหม่หลายรายการ" value={bulkValue} onChange={e=>setBulkValue(e.target.value)} placeholder={bulkField==='discount'?'เช่น 20% หรือ 20%+5%':'ระบุค่าใหม่'}/></label><button className="button primary" disabled={!bulkValue.trim()||!checkedIds.length||fetching||!!busy} onClick={bulkSave}>บันทึกให้ {checkedIds.length} รายการ</button><p>{bulkField==='sku'?'รายการที่เลือกจะใช้ SKU เดียวกันและรวมเป็นแถวเดียวเมื่อ Export':'ใช้ค่าใหม่กับแถวที่เลือก และคำนวณยอดหลังส่วนลดใหม่อัตโนมัติเมื่อบันทึก ต้นฉบับเก็บไว้ตรวจย้อนหลัง'}</p></div>}
            <div className={`table-scroll ${fetching?'loading-table':''}`}><table><thead><tr><th className="check-col"><input type="checkbox" aria-label="เลือกทั้งหมดในหน้านี้" disabled={!rows.length||fetching||!!busy} checked={rows.length>0&&rows.every(r=>checkedIds.includes(r.id))} ref={el=>{if(el)el.indeterminate=checkedIds.length>0&&!rows.every(r=>checkedIds.includes(r.id));}} onChange={e=>setCheckedIds(e.target.checked?rows.map(r=>r.id):[])}/></th><th className="index-col">#</th><th>สินค้า / Items</th><th>ลูกค้า · สาขา</th><th className="numeric">ราคาขาย/หน่วย</th><th className="numeric">ต้นทุน/หน่วยต้นทาง</th><th className="numeric">Qty</th><th>Discount</th><th className="numeric">ยอดขายรวม</th><th className="numeric">ต้นทุนรวมต้นทาง</th><th className="numeric">ยอดหลังส่วนลด</th><th>สถานะ</th><th/></tr></thead><tbody>{rows.map((r,i)=><tr key={r.id} className={checkedIds.includes(r.id)?'checked-row':''}><td className="check-col"><input type="checkbox" aria-label={`เลือกสินค้า ${r.sku||r.partner||r.id} แถว ${r.line}`} disabled={fetching||!!busy} checked={checkedIds.includes(r.id)} onChange={e=>setCheckedIds(v=>e.target.checked?[...v,r.id]:v.filter(id=>id!==r.id))}/></td><td className="row-number">{(page-1)*30+i+1}</td><td><button className="sku-button" onClick={()=>setSelected(r)}>{r.sku||<span className="missing">รอจับคู่ SKU</span>}</button><small>{r.barcode||r.partner||r.source}</small></td><td><span className="customer-name">{r.customer}</span><small>{r.branch_code?`${r.branch_code} · `:''}{r.branch}</small></td><td className="numeric">{number(r.price)}</td><td className="numeric">{number(r.source_cost_price)}<small title={r.source_cost_origin}>{r.source_cost_origin}</small></td><td className="numeric">{number(r.qty,0)}</td><td><span className={!r.discount?'missing':'discount-value'}>{r.discount?displayDiscount(r.discount):'ยังไม่ระบุ'}</span><small>{r.discount_kind}</small><small>{r.discount_origin}</small></td><td className="numeric">{number(r.calculated_gross)}<small>ต้นทาง {number(r.source_reference?r.source_reference.gross:r.gross)}</small></td><td className="numeric">{number(r.source_cost_total)}</td><td className="numeric">{number(r.calculated_net)}</td><td><span className={`badge ${r.status==='ready'?'ready':'blocked'}`}>{r.status==='ready'?<Check size={12}/>:<CircleAlert size={12}/>} {r.status==='ready'?'พร้อม':'ต้องแก้'}</span>{r.below_cost_status!=='none'&&<small className="cost-warning">ต่ำกว่าต้นทุน · {r.below_cost_status==='confirmed'?'ยืนยันแล้ว':'รอตรวจสอบ'}</small>}</td><td><button className="row-edit" aria-label={`แก้รายการ ${r.sku||r.barcode||r.id}`} onClick={()=>setSelected(r)}><ChevronRight size={17}/></button></td></tr>)}</tbody></table>{!rows.length&&<div className="empty"><div className="empty-icon"><FileSpreadsheet size={30}/></div><h3>{batch?.rows?'ไม่พบรายการตามเงื่อนไข':'เริ่มต้นด้วยรายงานขายของคุณ'}</h3><p>{batch?.rows?'ลองเปลี่ยนคำค้นหาหรือตัวกรอง':'เลือกไฟล์ หรือกดโหลดชุดตัวอย่าง เพื่อดูข้อมูลทั้ง 5 รูปแบบ'}</p></div>}</div>
            <div className="pagination"><span>{total?`${(page-1)*30+1}–${Math.min(page*30,total)} จาก ${number(total,0)} รายการ`:'0 รายการ'} <span className="pagination-note">· คลิกรายการเพื่อดูต้นทางและแก้ไข</span></span><div><button aria-label="หน้าก่อน" disabled={page<=1} onClick={()=>setPage(p=>p-1)}><ChevronLeft size={16}/></button><span>{page} / {Math.max(1,Math.ceil(total/30))}</span><button aria-label="หน้าถัดไป" disabled={page*30>=total} onClick={()=>setPage(p=>p+1)}><ChevronRight size={16}/></button></div></div>
          </>}
          {tab==='merged'&&<div className="merged-content"><div className="merged-heading"><div><h3>รวมสินค้า SKU เดียวกันเป็นแถวเดียว</h3><p>รวมเฉพาะรายการที่พร้อมจากทุกลูกค้าและสาขา · ใช้ SKU เท่านั้น ไม่ใช้ Barcode</p></div><strong>{number(batch?.ready||0,0)} รายการ <ArrowRight size={17}/> {number(batch?.merged_rows||0,0)} SKU</strong></div><div className="merged-totals"><span>จำนวนรวม<strong>{number(batch?.merged_qty,0)} ชิ้น</strong></span><span>ยอดก่อนหักรวม<strong>{number(batch?.merged_gross)}</strong></span><span>ยอดสุทธิรวม<strong>{number(batch?.merged_net)}</strong></span></div><div className="table-scroll"><table><thead><tr><th>Items / SKU</th><th className="numeric">Price เฉลี่ย</th><th className="numeric">Qty รวม</th><th>Discount</th><th className="numeric">ยอดก่อนหักรวม</th><th className="numeric">ยอดสุทธิรวม</th><th>ต้นทาง</th></tr></thead><tbody>{merged.map(r=><tr key={r.sku}><td><strong>{r.sku}</strong></td><td className="numeric">{number(r.price,6)}</td><td className="numeric">{number(r.qty,0)}</td><td>{displayDiscount(r.discount)}</td><td className="numeric">{number(r.gross)}</td><td className="numeric">{number(r.net)}</td><td><button className="text-button" onClick={()=>{setExactSku(r.sku);setQuery(r.sku);setCustomer('');setBelowCost('');setBranchKey('');setStatus('ready');setPage(1);setTab('rows');}}>ดู {r.source_count} รายการ <ChevronRight size={14}/></button></td></tr>)}</tbody></table>{!merged.length&&<div className="empty"><h3>ยังไม่มีรายการที่พร้อมรวม</h3></div>}</div><div className="pagination"><span>ทั้งหมด {number(mergedTotal,0)} SKU</span><div><button aria-label="หน้ารวมก่อนหน้า" disabled={mergedPage<=1} onClick={()=>setMergedPage(v=>v-1)}><ChevronLeft size={16}/></button><span>{mergedPage} / {Math.max(1,Math.ceil(mergedTotal/30))}</span><button aria-label="หน้ารวมถัดไป" disabled={mergedPage*30>=mergedTotal} onClick={()=>setMergedPage(v=>v+1)}><ChevronRight size={16}/></button></div></div><div className="logic-note"><ShieldCheck size={20}/><p>หากราคาต่างกัน: Price = ยอดก่อนหักรวม ÷ จำนวนรวม ส่วนลดภายในคำนวณจากยอดสุทธิรวมหลังแก้ไข ส่วนลดใน Excel ปัดเป็น 2 ตำแหน่งจึงอาจมีส่วนต่าง ไม่บวกราคาต่อหน่วยหรือเปอร์เซ็นต์ส่วนลดเข้าด้วยกัน · รายการขาย/คืนที่จำนวนรวมเป็นศูนย์ต้องตรวจแก้ก่อนส่งออก</p></div></div>}
          {tab==='mapping'&&<div className="mapping-content"><div className="mapping-grid"><div className="mapping-card"><div className="mapping-icon"><Database size={22}/></div><h3>ตารางอ้างอิงสินค้า</h3><p>จับคู่ Barcode หรือรหัสคู่ค้าเป็น SKU ที่ใช้ส่งออก<br/>เติมให้เฉพาะรายการที่ยังไม่มี SKU</p><div className="code-example">Barcode,SKU<br/>Customer,PartnerCode,SKU</div><p className="small-text">CSV (UTF-8) หรือ Excel · หัวตารางแถวแรก · ใช้รูปแบบใดรูปแบบหนึ่งด้านบน · หากรหัสเดียวกันชี้หลาย SKU ระบบจะให้ตรวจแก้</p><button className="button secondary" disabled={!batch||!!busy} onClick={()=>masterInput.current?.click()}><Upload size={16}/> นำเข้าตารางอ้างอิง</button><input ref={masterInput} type="file" hidden aria-label="อัปโหลดตารางอ้างอิง" accept=".csv,.xlsx" onChange={e=>{if(e.target.files?.[0])uploadMaster(e.target.files[0]);e.target.value='';}}/></div>
          <div className="mapping-card"><div className="mapping-icon amber-icon"><Settings2 size={22}/></div><h3>แก้ส่วนลดที่เป็นค่าเริ่มต้น 0%</h3><p>ใช้กับรายการที่ระบบตั้งค่าเริ่มต้น 0% เท่านั้น<br/>หากมีราคาสุทธิรายแถว ให้เปิดรายการเพื่อคำนวณย้อนกลับ</p><label>ลูกค้า<select value={ruleCustomer} onChange={e=>setRuleCustomer(e.target.value)}>{Array.from(new Set(['Outlet G624',...(batch?.groups.map(g=>g.customer)||[])])).map(c=><option key={c}>{c}</option>)}</select></label><label>ส่วนลดที่คุณยืนยัน<input aria-label="ส่วนลดกลุ่ม" value={ruleDiscount} onChange={e=>setRuleDiscount(e.target.value)} placeholder="เช่น 25% หรือ 20%+5%"/></label><label className="checkbox"><input type="checkbox" checked={ruleRemember} onChange={e=>setRuleRemember(e.target.checked)}/> จำกติกานี้สำหรับการนำเข้าครั้งถัดไป</label><button className="button secondary" disabled={!batch||!!busy||!ruleDiscount} onClick={applyRule}><Check size={16}/> ใช้กับค่าเริ่มต้น 0%</button></div></div>
          <div className="logic-note"><Sparkles size={20}/><div><strong>คำนวณย้อนกลับอย่างตรวจสอบได้</strong><p>ส่วนลดเทียบเท่า = (ยอดขายก่อนหัก − ยอดหลังส่วนลด) ÷ ยอดขายก่อนหัก × 100 · KING POWER ใช้ส่วนต่างรวมโดยไม่ถอด VAT ซ้ำ · ส่วนลด 20%+5% คำนวณต่อเนื่อง · ถ้าไม่มีข้อมูลพอคำนวณ ใช้ค่าเริ่มต้น 0% และแก้ไขได้</p></div></div></div>}
          {tab==='below-cost'&&batch&&<BelowCostReport batchId={batch.id} revision={revision} onShow={(shop,key)=>{showBranch(shop,key);setBelowCost('all');}}/>}
          {tab==='totals'&&<div className="totals-content"><h3>ตรวจยอดตามลูกค้า / Shop → สาขา</h3><p>ยอดรวมทุกรายการที่นำเข้า รวมรายการรอแก้และรายการคืน · คลิก Shop เพื่อดูแต่ละสาขา</p><div className="table-scroll"><table><thead><tr><th>ลูกค้า / Shop · สาขา</th><th className="numeric">จำนวนสุทธิ</th><th className="numeric">ยอดขายรวมต้นทาง</th><th className="numeric">ราคาขาย × จำนวน</th><th className="numeric">ต้นทุนรวมต้นทาง</th><th className="numeric">ยอดหลัง GP / ส่งคืนต้นทาง</th><th className="numeric">ยอดหลังส่วนลดคำนวณ</th><th>สถานะรายการ</th><th/></tr></thead><tbody>{batch?.groups.map(g=><Fragment key={g.customer}><tr className="shop-total"><td><button className="shop-toggle" aria-expanded={expandedShops.includes(g.customer)} onClick={()=>setExpandedShops(v=>v.includes(g.customer)?v.filter(x=>x!==g.customer):[...v,g.customer])}><ChevronRight size={16}/><strong>{g.customer}</strong></button><small>{g.rows.toLocaleString()} รายการ · {g.branches} สาขา/กลุ่ม</small></td><TotalCells totals={g}/><td><button className="text-button" aria-label={`ดูรายการทั้งหมด ${g.customer}`} onClick={()=>showBranch(g.customer)}>ดูรายการ</button></td></tr>{expandedShops.includes(g.customer)&&g.branch_groups.map(b=><tr className="branch-total" key={b.key}><td><strong>{b.branch}</strong><small>{b.branch_code?`รหัส ${b.branch_code} · `:''}{b.rows.toLocaleString()} รายการ</small></td><TotalCells totals={b}/><td><button className="text-button" aria-label={`ดูรายการ ${g.customer} ${b.branch_code||b.branch}`} onClick={()=>showBranch(g.customer,b.key)}>ดูรายการ <ChevronRight size={14}/></button></td></tr>)}</Fragment>)}</tbody></table></div>{!batch?.rows&&<div className="empty"><h3>นำเข้ารายงานเพื่อดูยอด Shop และสาขา</h3></div>}<div className="logic-note"><ShieldCheck size={20}/><p>ต้นทุนกับยอดหลัง GP เป็นคนละข้อมูล: Big C ใช้ราคาทุน L × จำนวน K; Outlet ไม่ระบุต้นทุน จึงแสดง “ไม่ระบุ” แม้ตั้งส่วนลด 0% · ยอดแต่ละสาขารวมกลับเป็นยอดของ Shop เดียวกัน ใช้ฐานราคาตามไฟล์โดยไม่ปรับ VAT เพิ่ม · ยอดสุทธิคำนวณรวมส่วนลดค่าเริ่มต้น 0% ที่แก้ภายหลังได้ และแสดงจำนวนไว้ให้ตรวจสอบ · ยอดที่จะส่งออกเฉพาะรายการที่พร้อมดูได้ใน “รวมตาม SKU”</p></div></div>}
        </section>
        <section className="export-bar"><div className="export-description"><div className="excel-icon"><FileSpreadsheet size={24}/></div><div><strong>รวม SKU ซ้ำเป็นแถวเดียว พร้อมส่งออก</strong><p>Sample · Items / Price / Qty / Discount <span>· รวมทุกลูกค้าและสาขา</span></p></div></div><div className="export-action"><span className="export-counts">พร้อม {number(batch?.ready||0,0)} รายการ → {number(batch?.merged_rows||0,0)} SKU · ยังไม่ส่งออก {number(batch?.blocked||0,0)} รายการ{batch?.file_errors?` และ ${batch.file_errors} ไฟล์`:''}<small>ส่งออกรายการของชุดนี้ทั้งหมด ไม่จำกัดตามตัวกรองตาราง</small></span><div className="export-buttons"><button className="button secondary" disabled={!batch?.exportable||!!busy} onClick={()=>exportFile('all')}><ArrowDownToLine size={17}/> Export Excel</button><button className="button primary" disabled={!batch?.ready||!!busy} onClick={()=>exportFile('ready')}><ArrowDownToLine size={17}/> Export เฉพาะรายการที่พร้อม</button></div></div></section>
        <footer className="footer"><span>ConsignmentSystem <span> / </span> LOCAL · BETA 1</span><span>ไฟล์ต้นฉบับคงเดิม · รวมตาม SKU ในไฟล์ส่งออก</span></footer>
      </div>
    </main>
    {busy&&!sheetRequest&&<LoadingOverlay message={busy}/>}
    {sheetRequest&&<SheetPicker request={sheetRequest} onDone={finishSheets}/>}
    {selected&&batch&&<EditDrawer row={selected} batchId={batch.id} onClose={()=>setSelected(null)} onUpdated={async()=>{await refresh(batch.id);}} onSaved={async()=>{setSelected(null);}}/>}
  </div>;
}

function EditDrawer({row:initial,batchId,onClose,onSaved,onUpdated}:{row:SaleRow;batchId:string;onClose:()=>void;onSaved:()=>Promise<void>;onUpdated:()=>Promise<void>}){
  const [r,setRecord]=useState(initial);
  const [sku,setSku]=useState(r.sku);const [price,setPrice]=useState(r.price||'');const [qty,setQty]=useState(r.qty||'');const [discount,setDiscount]=useState(displayDiscount(r.discount));const [discountChanged,setDiscountChanged]=useState(false);const [net,setNet]=useState(r.net||'');const [netChanged,setNetChanged]=useState(false);const [remember,setRemember]=useState(false);const [error,setError]=useState('');const [saving,setSaving]=useState(false);
  const [preview,setPreview]=useState<SaleRow|null>(r);
  const [previewError,setPreviewError]=useState('');
  useEffect(()=>{
    const controller=new AbortController();
    setPreview(null);setPreviewError('');
    const timer=setTimeout(async()=>{
      const payload:Record<string,string>={price,qty};
      if(netChanged)payload.net=net;else if(discountChanged)payload.discount=discount;
      try{
        const result=await api<SaleRow>(`/batches/${batchId}/rows/${r.id}/preview`,{...json('POST',payload),signal:controller.signal});
        if(!controller.signal.aborted)setPreview(result);
      }catch(e){if(!controller.signal.aborted)setPreviewError(e instanceof Error?e.message:'คำนวณไม่ได้');}
    },250);
    return()=>{clearTimeout(timer);controller.abort();};
  },[batchId,r.id,price,qty,discount,discountChanged,net,netChanged]);
  useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const key=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!saving)onClose();if(e.key==='Tab'){const all=Array.from(document.querySelectorAll<HTMLElement>('.drawer button:not(:disabled),.drawer input:not(:disabled),.drawer summary,.drawer a[href]'));const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',key);document.body.style.overflow='';previous?.focus();};},[onClose]);
  const save=async()=>{setSaving(true);setError('');try{const payload:Record<string,unknown>={sku,price,qty,remember};if(netChanged){payload.net=net;}else if(discountChanged){payload.discount=discount;}const result=await api<SaleRow>(`/batches/${batchId}/rows/${r.id}`,json('PATCH',payload));setRecord(result);await onUpdated();if(result.errors.length){setError('บันทึกแล้ว แต่ยังต้องแก้: '+result.errors.join(' · '));setDiscount(displayDiscount(result.discount));setNet(result.net||'');setDiscountChanged(false);setNetChanged(false);}else await onSaved();}catch(e){setError(e instanceof Error?e.message:'บันทึกไม่ได้');}finally{setSaving(false);}};
  return <div className="drawer-overlay" onClick={e=>{if(e.target===e.currentTarget&&!saving)onClose();}}><section className="drawer" role="dialog" aria-modal="true" aria-labelledby="edit-title"><div className="drawer-heading"><div><div className="eyebrow">REVIEW RECORD</div><h2 id="edit-title">ตรวจและแก้ไขรายการ</h2></div><button className="icon-button" aria-label="ปิดรายการ" disabled={saving} onClick={onClose}><X size={21}/></button></div><div className="drawer-body"><div className="record-source"><strong>{r.customer}</strong><span>{r.branch_code} {r.branch}</span><small>{r.source}<br/>{r.sheet} · แถว/บรรทัด {r.line} {r.source_columns?`· คอลัมน์ ${r.source_columns}`:''}</small></div>
  {!!r.errors.length&&<div className="issue-box">{r.errors.map(e=><p key={e}><CircleAlert size={14}/>{e}</p>)}</div>}
  <div className="edit-grid"><label className="full">Items / SKU<input autoFocus aria-label="แก้ SKU" value={sku} onChange={e=>setSku(e.target.value)}/><small>{r.sku_origin} · Barcode {r.barcode||'—'} · รหัสคู่ค้า {r.partner||'—'}</small></label><label>Price ก่อนหัก<input inputMode="decimal" aria-label="แก้ Price" value={price} onChange={e=>setPrice(e.target.value)}/></label><label>Qty<input inputMode="decimal" aria-label="แก้ Qty" value={qty} onChange={e=>setQty(e.target.value)}/></label><label className="full">Discount<input aria-label="แก้ Discount" value={netChanged?(preview?displayDiscount(preview.discount):''):discount} disabled={netChanged} onChange={e=>{setDiscount(e.target.value);setDiscountChanged(true);}} placeholder="เช่น 25% หรือ 20%+5%"/><small>{netChanged?'ระบบจะคำนวณจากยอดสุทธิที่กรอกเมื่อบันทึก':r.discount_origin}</small></label><label className="full">ยอดสุทธิรวมหลังหักส่วนลด (ถ้ามี)<input aria-label="แก้ยอดสุทธิ" inputMode="decimal" value={netChanged?net:(preview?.net??'')} onChange={e=>{setNet(e.target.value);setNetChanged(true);}} placeholder="กรอกเพื่อคำนวณส่วนลดย้อนกลับ"/><small>เทียบกับยอดขาย Price × Qty เพื่อคำนวณส่วนลดย้อนกลับ ไม่ใช่ราคาต่อชิ้น</small></label></div>
  <p role="status">{previewError||(!preview?'กำลังคำนวณยอด…':'ยอดคำนวณใหม่อัตโนมัติ · กดบันทึกเพื่อใช้ค่าใหม่')}</p>
  <label className="checkbox"><input type="checkbox" checked={remember} onChange={e=>setRemember(e.target.checked)} disabled={!r.barcode&&!r.partner}/> จำ Barcode / รหัสคู่ค้า → SKU นี้</label>
  <div className="calculation"><span>ราคาขายต่อหน่วย<strong>{number(preview?.price)}</strong></span><span>ราคาต้นทุนต่อหน่วยต้นทาง<strong>{number(r.source_cost_price)}</strong></span><span>ราคาขาย × จำนวน<strong>{number(preview?.calculated_gross)}</strong></span><span>ต้นทุนรวมต้นทาง<strong>{number(r.source_cost_total)}</strong></span><span>ยอดขายรวมต้นทาง<strong>{number(r.source_reference?r.source_reference.gross:r.gross)}</strong></span><span>ยอดหลัง GP / ส่งคืนต้นทาง<strong>{number(r.source_reference?r.source_reference.net:r.net)}</strong></span><span>ยอดหลังส่วนลดคำนวณ<strong>{number(preview?.calculated_net)}</strong></span></div><p className="vat-note">อัตราที่ใช้: {r.discount_kind}<br/>GP ต้นทาง: {r.source_gp?displayDiscount(r.source_gp):'ไม่ระบุ'} · MG ต้นทาง: {r.source_mg?displayDiscount(r.source_mg):'ไม่ระบุ'}<br/>ต้นทุน: {r.source_cost_origin}<br/>ฐาน VAT ต้นทาง: {r.vat}<br/>{r.valuation&&<>ตั้งค่า: ราคาขาย {r.valuation.sale_basis} / ต้นทุน {r.valuation.cost_basis} / ยอดหลังหัก {r.valuation.settlement_basis} · VAT {r.valuation.vat_rate}%<br/></>}Export ส่วนลด 2 ตำแหน่ง อาจมีส่วนต่างจากการปัดเศษ · อัตราคำนวณภายใน: {r.discount}</p>
  {r.below_cost_status!=='none'&&<BelowCostConfirmationForm record={r} batchId={batchId} disabled={saving||!!r.errors.length||sku!==r.sku||price!==(r.price||'')||qty!==(r.qty||'')||discountChanged||netChanged} onBusy={setSaving} onSaved={async result=>{setRecord(result);await onUpdated();}}/>}
  {!!r.warnings.length&&<details><summary>ข้อสังเกตจากต้นทาง ({r.warnings.length})</summary><ul>{r.warnings.map(w=><li key={w}>{w}</li>)}</ul></details>}
  <details><summary>ดูข้อมูลต้นทาง</summary><div className="raw-values">{Object.entries(r.raw).map(([k,v])=><div key={k}><strong>{k}</strong><span>{v}</span></div>)}</div><a className="text-button" href={`/api/batches/${batchId}/files/${r.file_id}`}><ArrowDownToLine size={15}/> ดาวน์โหลดต้นฉบับ</a></details>
  <details><summary>ประวัติแก้ไข ({r.edits.length})</summary><pre className="audit-json">{JSON.stringify(r.edits,null,2)}</pre></details>
  {error&&<div className="notice error" role="alert">{error}</div>}</div><div className="drawer-footer"><button className="button secondary" disabled={saving} onClick={onClose}>ปิด</button><button className="button primary" disabled={saving} onClick={save}>{saving?<LoaderCircle className="spin" size={16}/>:<Check size={16}/>} บันทึกและตรวจยอด</button></div></section></div>;
}

function TotalCells({totals:g}:{totals:Totals}){
  return <><td className="numeric">{number(g.qty,0)}</td><td className="numeric">{number(g.gross)}{g.exvat_rows>0&&<small>ยอดขายไม่รวม VAT {number(g.source_sales_ex_vat)}</small>}</td><td className="numeric">{g.gross_rows?number(g.calculated_gross):'—'}</td><td className="numeric">{g.cost_rows?number(g.source_cost_total):'ไม่ระบุ'}<small>{g.cost_rows} / {g.rows} รายการมีข้อมูลต้นทุน</small></td><td className="numeric">{g.net_rows?number(g.net):'ไม่ระบุ'}<small>{g.net_rows} / {g.rows} รายการมีฐานเทียบ</small></td><td className="numeric">{g.calculated_rows?number(g.calculated_net):'—'}<small>{g.calculated_rows} / {g.rows} รายการคำนวณได้</small>{g.default_discount_rows>0&&<small className="default-total-note">ค่าเริ่มต้น 0%: {g.default_discount_rows} รายการ</small>}</td><td><span className="badge ready">พร้อม {g.ready.toLocaleString()}</span>{g.blocked>0&&<span className="badge blocked">ต้องแก้ {g.blocked.toLocaleString()}</span>}</td></>;
}

function LoadingOverlay({message}:{message:string}){
  const panel=useRef<HTMLDivElement>(null);
  useEffect(()=>{const previous=document.activeElement as HTMLElement|null;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';panel.current?.focus();return()=>{document.body.style.overflow=overflow;previous?.focus();};},[]);
  return <div className="operation-overlay"><div className="operation-card" role="dialog" aria-modal="true" aria-labelledby="loading-title" aria-describedby="loading-description" tabIndex={-1} ref={panel}><div className="operation-spinner"><LoaderCircle className="spin" size={40} aria-hidden="true"/></div><h2 id="loading-title">กำลังดำเนินการ</h2><p role="status" aria-live="polite">{message}</p><small id="loading-description">กรุณารอสักครู่ ระบบกำลังประมวลผลข้อมูล</small><div className="operation-track" aria-hidden="true"><span/></div></div></div>;
}

function BelowCostConfirmationForm({record:r,batchId,disabled,onBusy,onSaved}:{record:SaleRow;batchId:string;disabled:boolean;onBusy:(value:boolean)=>void;onSaved:(row:SaleRow)=>Promise<void>}){
  const [by,setBy]=useState('');const [reason,setReason]=useState('');const [basis,setBasis]=useState('');const [evidence,setEvidence]=useState('');const [comparable,setComparable]=useState(false);const [error,setError]=useState('');
  const confirm=async()=>{onBusy(true);setError('');try{const result=await api<SaleRow>(`/batches/${batchId}/rows/${r.id}/confirm-below-cost`,json('POST',{confirmed_by:by,reason,vat_basis:basis,evidence,comparable}));await onSaved(result);}catch(e){setError(e instanceof Error?e.message:'บันทึกไม่ได้');}finally{onBusy(false);}};
  return <section className="below-cost-review"><h3>ขายต่ำกว่าต้นทุน — {r.below_cost_status==='confirmed'?'ยืนยันแล้ว':'รอตรวจสอบ'}</h3><p>คำเตือนทางธุรกิจแยกจากข้อผิดพลาดการคำนวณ · {r.comparison_basis==='ex_vat'?'ส่วนต่างในฐานไม่รวม VAT':'ส่วนต่างจากตัวเลขต้นทาง (ยังไม่ทราบฐาน)'} {number(r.below_cost_difference)} บาท ก่อนหักส่วนลด / {number(r.below_cost_after_discount_difference)} บาท หลังหักส่วนลด</p><p>ยังไม่ถือเป็นขาดทุนที่ยืนยันแล้วหากราคาขายและต้นทุนต่างฐาน VAT</p>
  {r.below_cost_confirmation&&<div className="confirmed-info"><strong>{r.below_cost_confirmation.confirmed_by}</strong> · {new Date(r.below_cost_confirmation.at).toLocaleString('th-TH')}<p>{r.below_cost_confirmation.reason}</p><p>ฐาน VAT: {r.below_cost_confirmation.vat_basis} · {r.below_cost_confirmation.comparable?'ยืนยันเทียบฐานเดียวกัน':'ยังไม่ยืนยันว่าเทียบฐานเดียวกัน'}</p><p>อ้างอิง: {r.below_cost_confirmation.evidence||'ไม่ระบุ'}</p></div>}
  {r.below_cost_status==='pending'&&<fieldset disabled={disabled}><label>ผู้ยืนยัน<input aria-label="ผู้ยืนยันราคาต่ำกว่าต้นทุน" value={by} onChange={e=>setBy(e.target.value)} maxLength={150}/></label><label>เหตุผล / หมายเหตุ<input aria-label="เหตุผลราคาต่ำกว่าต้นทุน" value={reason} onChange={e=>setReason(e.target.value)} maxLength={1000}/></label><label>ฐาน VAT ของราคาขายและต้นทุน<input aria-label="ฐาน VAT ที่ยืนยัน" value={basis} onChange={e=>setBasis(e.target.value)} placeholder="ระบุฐานของทั้งสองราคา หรือระบุว่ายังไม่ทราบ" maxLength={500}/></label><label>หลักฐานอ้างอิง (ถ้ามี)<input aria-label="หลักฐานยืนยันราคา" value={evidence} onChange={e=>setEvidence(e.target.value)} placeholder="เช่น วันที่ Sales ยืนยัน / เลขที่เอกสาร" maxLength={1000}/></label><label className="checkbox"><input type="checkbox" checked={comparable} onChange={e=>setComparable(e.target.checked)}/> ยืนยันว่าราคาขายและต้นทุนเทียบในฐาน VAT เดียวกันได้</label><button className="button secondary" disabled={!by.trim()||!reason.trim()||!basis.trim()} onClick={confirm}>ยืนยันข้อมูลขายต่ำกว่าต้นทุน</button><p>บันทึกการแก้ไขราคา/ส่วนลดและแก้ข้อผิดพลาดให้เรียบร้อยก่อนยืนยัน</p></fieldset>}
  {error&&<p role="alert">{error}</p>}
  {!!r.below_cost_confirmations?.length&&<details><summary>ประวัติการยืนยัน ({r.below_cost_confirmations.length})</summary>{r.below_cost_confirmations.map((c,i)=><p key={i}>{new Date(c.at).toLocaleString('th-TH')} · {c.confirmed_by} · {c.reason} · VAT: {c.vat_basis} · อ้างอิง: {c.evidence||'—'}</p>)}</details>}</section>;
}

type LossGroup={comparison_basis:string;customer:string;branch:string;branch_code:string;key:string;rows:number;pending:number;confirmed:number;comparable_rows:number;qty:string;sales:string;cost:string;difference:string;after_discount_difference:string;after_discount_rows:number};
function BelowCostReport({batchId,revision,onShow}:{batchId:string;revision:number;onShow:(shop:string,key:string)=>void}){
  const [report,setReport]=useState<{rows:number;pending:number;confirmed:number;groups:LossGroup[]}|null>(null);const [error,setError]=useState('');
  useEffect(()=>{const abort=new AbortController();setReport(null);setError('');api<{rows:number;pending:number;confirmed:number;groups:LossGroup[]}>(`/batches/${batchId}/below-cost`,{signal:abort.signal}).then(setReport).catch(e=>{if(e.name!=='AbortError')setError(e.message);});return()=>abort.abort();},[batchId,revision]);
  return <div className="totals-content below-cost-report"><h3>รายการขายต่ำกว่าต้นทุน แยก Shop / สาขา</h3><p>เฉพาะรายการขายจำนวนบวกที่ราคาขายต่อหน่วยต่ำกว่าต้นทุนต้นทาง · เมื่อกำหนดฐานราคาครบ จะเทียบในฐานไม่รวม VAT; กรณียังไม่ทราบจะแยกกลุ่มตัวเลขต้นทาง</p>{error?<p role="alert">{error}</p>:!report?<p role="status">กำลังตรวจรายการ…</p>:<><div className="merged-totals"><span>ทั้งหมด<strong>{report.rows} รายการ</strong></span><span>รอตรวจสอบ<strong>{report.pending}</strong></span><span>ยืนยันแล้ว<strong>{report.confirmed}</strong></span></div><div className="table-scroll"><table><thead><tr><th>Shop / สาขา</th><th className="numeric">จำนวน</th><th className="numeric">ยอดขาย</th><th className="numeric">ต้นทุน × จำนวน</th><th className="numeric">ต้นทุน − ยอดขาย</th><th className="numeric">ต้นทุน − ยอดหลังส่วนลด</th><th>การยืนยัน</th><th/></tr></thead><tbody>{report.groups.map(g=><tr key={g.customer+g.key+g.comparison_basis}><td><strong>{g.customer}</strong><small>{g.branch_code} {g.branch}</small><small>{g.comparison_basis==='ex_vat'?'เทียบในฐานไม่รวม VAT':'ยังไม่ทราบฐาน เปรียบเทียบตัวเลขต้นทาง'}</small></td><td className="numeric">{number(g.qty,0)}</td><td className="numeric">{number(g.sales)}</td><td className="numeric">{number(g.cost)}</td><td className="numeric">{number(g.difference)}</td><td className="numeric">{g.after_discount_rows?number(g.after_discount_difference):'—'}<small>{g.after_discount_rows}/{g.rows} รายการคำนวณได้</small></td><td><span className="badge blocked">รอ {g.pending}</span><span className="badge ready">ยืนยัน {g.confirmed}</span><small>ยืนยันฐานเดียวกัน {g.comparable_rows}/{g.rows}</small></td><td><button className="text-button" onClick={()=>onShow(g.customer,g.key)}>ดูรายการ</button></td></tr>)}</tbody></table></div>{!report.rows&&<div className="empty">ไม่พบรายการขายต่ำกว่าต้นทุนที่มีข้อมูลต้นทุนให้เทียบ</div>}<div className="logic-note">การยืนยันไม่เปลี่ยนราคา GP หรือสูตร · ข้อผิดพลาดยังต้องแก้ก่อน Export · เมื่อค่าที่ใช้ยืนยันเปลี่ยน รายการจะกลับมารอตรวจสอบ</div></>}</div>;
}
